<?php declare(strict_types=1);namespace App\Services;use Dompdf\Dompdf;final class ReportService{public function csv(array $rows):string{$f=fopen('php://temp','r+');if($rows){fputcsv($f,array_keys($rows[0]));foreach($rows as $r)fputcsv($f,$r);}rewind($f);return stream_get_contents($f);}public function pdf(string $html):string{$pdf=new Dompdf();$pdf->loadHtml($html);$pdf->render();return $pdf->output();}}
